<?php
namespace App\Livewire;
use App\Models\AttendanceRecord;use App\Models\GradingScale;use App\Models\Student;use App\Models\Term;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\DB;use Livewire\Attributes\Layout;use Livewire\Component;
#[Layout('layouts.app')] class StudentTermReport extends Component {public string $termId='',$studentId='';public function mount():void{$this->termId=(string)Auth::user()->school->currentTerm()?->id;}public function render(){$school=Auth::user()->school;$term=Term::where('school_id',$school->id)->find($this->termId);$students=Student::with('schoolClass')->where('school_id',$school->id)->where('status','active')->orderBy('name')->get();$student=$this->studentId?Student::with(['schoolClass','stream','guardians'])->where('school_id',$school->id)->find($this->studentId):null;$attendance=collect();$examResults=collect();if($student&&$term){$attendance=AttendanceRecord::where(['school_id'=>$school->id,'term_id'=>$term->id,'student_id'=>$student->id])->get();$examResults=DB::table('exam_marks')->join('exam_papers','exam_papers.id','=','exam_marks.exam_paper_id')->join('exams','exams.id','=','exam_papers.exam_id')->join('exam_paper_submissions','exam_paper_submissions.exam_paper_id','=','exam_papers.id')->where(['exam_marks.student_id'=>$student->id,'exams.school_id'=>$school->id,'exams.term_id'=>$term->id,'exam_paper_submissions.status'=>'approved'])->select('exams.name',DB::raw('round(avg(exam_marks.score / exam_papers.maximum_score * 100),2) as average'))->groupBy('exams.id','exams.name')->get();}return view('livewire.student-term-report',['terms'=>Term::where('school_id',$school->id)->latest('year')->get(),'students'=>$students,'term'=>$term,'student'=>$student,'attendance'=>$attendance,'examResults'=>$examResults,'pageTitle'=>'Student Term Report']);}}
